mapper.select:
SELECT T1.ENTRUST_ID entrustId, T1.ENTRUST_STATUS entrustStatus, T1.PORTFOLIO_ID portfolioId, T4.ASSET_TYPE1 assetType1, T2.PORTFOLIO_NAME portfolioName, T1.PRICE*100 price, T4.TERM_TYPE termType, T4.TERM_DAYS repoTerm, T4.BUSI_PS ps, T1.ENTRUST_AMT entrustAmt, T1.CCY ccy, T1.VDATE vdate, T1.MDATE mdate, T1.PRICE_MODEL priceModel, NVL(T5.FINISH_AMT,0) finishAmt, round(NVL(T5.FINISH_AMT,0)/T1.ENTRUST_AMT,4)*100 transactioncom, T1.REMARK remark FROM ETR_ENTRUST T1 LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID INNER JOIN ETR_ENTRUST_ADD T4 ON T4.ENTRUST_ID = T1.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(NVL(FINISH_AMT,0)) FINISH_AMT FROM ETR_FINISH_STATUS where ENTRUST_ID != TRADE_ID GROUP BY ENTRUST_ID) T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY T6 ON T2.PORTFOLIO_ID = T6.PORTFOLIO_ID
AND T6.USER_ID = #{userId}
AND (T2.PORTFOLIO_ID IN
#{prot}
or T2.PARENT_PORTFOLIO_ID IN
#{prot}
)
AND T4.ASSET_TYPE1 = #{assetType1}
AND T4.TERM_TYPE = #{termType}
AND T1.CCY = #{ccy}
AND T1.PS=#{ps}
AND T1.ENTRUST_STATUS = #{entrustStatus}
AND T1.VDATE >=to_date(#{startDate},'yyyy-MM-dd')
AND T1.MDATE <=to_date(#{endDate},'yyyy-MM-dd')
AND T1.PRICE_MODEL = #{priceModel}
AND T1.FINPROD_TYPE2 in (#{FINPROD_TYPE2_Z},#{FINPROD_TYPE2_N})
AND T1.TRADE_MARKET in
#{currTradeMarket}
order by T1.ENTRUST_ID DESC

SELECT T1.PORTFOLIO_ID code, T1.PORTFOLIO_ID name, T1.PORTFOLIO_NAME shortName, T1.PORTFOLIO_ID hidCode FROM PTL_PORTFOLIO T1 INNER JOIN PTL_PORTFOLIO_AUTHORITY T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID AND T2.USER_ID = #{userId}
T1.PORTFOLIO_ID like concat('%',concat(#{param},'%')) or T1.PORTFOLIO_NAME like concat('%',concat(#{param},'%'))
AND T1.PORTFOLIO_TYPE IN (#{portType}, #{portType1})

SELECT T1.PORTFOLIO_ID id, T1.PORTFOLIO_NAME text FROM PTL_PORTFOLIO T1 INNER JOIN PTL_PORTFOLIO_AUTHORITY T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID AND T2.USER_ID = #{userId}
T1.PORTFOLIO_ID = #{initValue}
AND (T1.PORTFOLIO_ID like concat('%',concat(#{search},'%')) or T1.PORTFOLIO_NAME like concat('%',concat(#{search},'%')))
AND T1.PORTFOLIO_TYPE IN (#{portType}, #{portType1})

SELECT T1.ENTRUST_ID entrustId, T1.PORTFOLIO_ID portfolioId, T1.VDATE vdate, T1.MDATE mdate, T6.ASSET_TYPE1 assetType1, T6.VDATE vdateAdd, T6.MDATE mdateAdd, T6.TERM_DAYS repoTerm, T6.SETTLE_SPREED settleSpeed, T6.CASH_USEDATE availableDay, T6.SEC_ACCT_ID securitiesCust, T6.TERM_TYPE termType, T1.CCY ccy, T1.PS ps, T1.PRICE*100 price, T1.PRICE_MODEL priceModel, T1.ENTRUST_AMT entrustAmt, T6.MIN_AMT minAmt, T1.TRADE_MARKET tradeMarket, T1.CALENDAR_ID calendarId, T1.PRO_AVAILABLE_CASH proAvailableCash, T1.ACC_AVAILABLE_CASH accAvailableCash, T1.REMARK remark, T1.COUNTER_ID counterId, T1.COUNTER_TRADER counterTrader, T1.CONTACT_INFO contactInfo, T2.TRADER trader, T1.INV_MANAGER_ID invManagerId, T1.CHL_ID FROM ETR_ENTRUST T1 LEFT JOIN ETR_DISTRIBUTE T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD T6 ON T1.ENTRUST_ID = T6.ENTRUST_ID
T1.ENTRUST_ID = #{entrustId}
union all
SELECT T1.ENTRUST_ID entrustId, T1.PORTFOLIO_ID portfolioId, T1.VDATE vdate, T1.MDATE mdate, T6.ASSET_TYPE1 assetType1, T6.VDATE vdateAdd, T6.MDATE mdateAdd, T6.TERM_DAYS repoTerm, T6.SETTLE_SPREED settleSpeed, T6.CASH_USEDATE availableDay, T6.SEC_ACCT_ID securitiesCust, T6.TERM_TYPE termType, T1.CCY ccy, T1.PS ps, T1.PRICE * 100 price, T1.PRICE_MODEL priceModel, T1.ENTRUST_AMT entrustAmt, T6.MIN_AMT minAmt, T1.TRADE_MARKET tradeMarket, T1.CALENDAR_ID calendarId, T1.PRO_AVAILABLE_CASH proAvailableCash, T1.ACC_AVAILABLE_CASH accAvailableCash, T1.REMARK remark, T1.COUNTER_ID counterId, T1.COUNTER_TRADER counterTrader, T1.CONTACT_INFO contactInfo, T2.TRADER trader, T1.INV_MANAGER_ID invManagerId, T1.CHL_ID FROM WFL_ETR_ENTRUST T1 LEFT JOIN ETR_DISTRIBUTE T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN WFL_ETR_ENTRUST_ADD T6 ON T1.ENTRUST_ID = T6.ENTRUST_ID
T1.ENTRUST_ID = #{entrustId}

select TYPE_6 assetType1 from FIN_PRODUCT_TYPE
where 
FINPROD_ID = #{finprodId}

SELECT distinct A.ACCT_NO hidCode, A.ACCT_NO code, B.SEC_ACCT_NAME name, B.SEC_ACCT_NAME shortName FROM PTL_SEC_ACCT A INNER JOIN STL_SEC_ACCT_INFO B ON A.ACCT_NO = B.SEC_ACCT_ID
PORTFOLIO_ID = #{portfolioId}
AND ( A.ACCT_NO LIKE CONCAT('%', CONCAT(#{search}, '%')) OR B.SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.ACCT_NO = #{initValue}
AND TRADE_PLACE = #{tradeMarket}

select AMOUNT from PTL_CASH_POSITION where
PORTFOLIO_ID=#{finprodId}
and HODING_TYPE='03'
and CDATE = #{platDate,jdbcType=DATE}
and CHL_FINPROD_ID=#{chlId}

select min(MDATE) FROM FIN_PRODUCT
FINPROD_MARKET_ID in
#{item}
